// Types defined inline for browser context (no imports)
// NOTE: renderer.ts must stay a SCRIPT (no top-level import/export). Its inline
// interfaces rely on global declaration-merging with types.d.ts; an `import`
// turns this file into a module and breaks that merge. Shared pure helpers are
// therefore mirrored here as script-scope functions (see computeSubTimestampSpread).
interface FileStats {
  path: string;
  size: number;
  totalLines: number;
  indexedAt: number;
}

interface LogLine {
  lineNumber: number;
  text: string;
  level?: string;
  timestamp?: string;
  filtered?: boolean;
  duplicateCount?: number;
}

interface ChunkResponse {
  lines: LogLine[];
  startLine: number;
  endLine: number;
}

interface SearchResult {
  lineNumber: number;
  column: number;
  length: number;
  text: string;
  displayIndex?: number;
}

interface HiddenMatch {
  lineNumber: number;
  column: number;
  length: number;
  lineText: string;
}

interface CrashEntry {
  text: string;
  lineNumber: number;
  level?: string;
  channel?: string;
  keyword: string;
}

interface FailingComponent {
  name: string;
  errorCount: number;
  warningCount: number;
  sampleLine: number;
}

interface FilterSuggestion {
  id: string;
  title: string;
  description: string;
  type: 'exclude' | 'include' | 'level';
  filter: {
    excludePatterns?: string[];
    includePatterns?: string[];
    levels?: string[];
    channel?: string;
  };
}

interface AnalysisInsights {
  crashes: CrashEntry[];
  topFailingComponents: FailingComponent[];
  filterSuggestions: FilterSuggestion[];
}

interface AnalysisResult {
  stats: { totalLines: number; analyzedLines: number };
  levelCounts: Record<string, number>;
  timeRange?: { start: string; end: string };
  analyzerName: string;
  analyzedAt: number;
  insights: AnalysisInsights;
  density?: {
    buckets: number;
    fatal: number[];
    error: number[];
    warning: number[];
    info: number[];
    debug?: number[];
    verbose?: number[];
  };
}

interface IncludePattern {
  pattern: string;
  caseSensitive: boolean;
}

interface FilterPreset {
  id: string;
  name: string;
  levels: string[];
  includePatterns: Array<{ pattern: string; caseSensitive: boolean }>;
  excludePatterns: string[];
  matchCase: boolean;
  exactMatch: boolean;
  contextLines: number;
}

interface FilterConfig {
  minFrequency?: number;
  maxFrequency?: number;
  excludePatterns: string[];
  includePatterns: IncludePattern[];
  levels: string[];
  matchCase?: boolean;
  exactMatch?: boolean;
  timeRange?: { start: string; end: string };
  contextLines?: number;
  // Advanced filter support
  advancedFilter?: AdvancedFilterConfig;
}

// Advanced Filter Types
type FilterRuleType = 'contains' | 'not_contains' | 'level' | 'not_level' | 'regex' | 'not_regex' | 'column';

interface FilterRule {
  id: string;
  type: FilterRuleType;
  value: string;
  caseSensitive?: boolean;
  columnIndex?: number;                         // for type 'column': which column to test
  columnOp?: 'equals' | 'contains' | 'regex';   // for type 'column': how to compare the cell
}

interface FilterGroup {
  id: string;
  operator: 'AND' | 'OR';
  rules: FilterRule[];
}

interface AdvancedFilterConfig {
  enabled: boolean;
  groups: FilterGroup[];
  contextLines?: number;
  delimiter?: string;                           // column delimiter, so 'column' rules can split the line
}

interface Bookmark {
  id: string;
  lineNumber: number;
  label?: string;
  color?: string;
  createdAt: number;
}

interface HighlightConfig {
  id: string;
  pattern: string;
  isRegex: boolean;
  matchCase: boolean;
  wholeWord: boolean;
  backgroundColor: string;
  textColor?: string;
  includeWhitespace: boolean;
  highlightAll: boolean; // true = all occurrences, false = first only per line
}

// Folder State - stores opened folders and their files
interface LocalFolderFile {
  name: string;
  path: string;
  size?: number;
  fileType?: 'text' | 'image' | 'video';
  isDirectory?: boolean;
  children?: LocalFolderFile[];
  collapsed?: boolean;
  // Last-modified / creation time (epoch-ms) from the folder scan. Drives the tree's
  // "updated" label, the recent-file highlight and the recency sort. Absent for remote
  // (SSH) entries and any entry whose stat failed.
  mtimeMs?: number;
  birthtimeMs?: number;
  // Lazy tree: shallow-scan hint that this directory has expandable content, plus
  // transient per-node load state (populated when the user expands it or reveal walks
  // through it). Local and remote subfolders both load their children on demand.
  hasChildren?: boolean;
  _loaded?: boolean;
  _loading?: boolean;
  _loadError?: string;
}

interface FolderState {
  path: string;
  name: string;
  files: LocalFolderFile[];
  collapsed: boolean;
  isRemote?: boolean;
  sshHost?: string;
  connectionId?: string; // live connection ID to disconnect when folder is removed
}

// Column visibility state
interface ColumnConfig {
  delimiter: string;
  delimiterName: string;
  columns: Array<{
    index: number;
    sample: string[];
    visible: boolean;
    name?: string; // user-assigned column name (Columns panel) — drives labels, save/template, filter
    muted?: boolean; // dim this column in place (view-only de-emphasis; the column-level line-mute)
  }>;
  // Pattern mode (Phase 2): columns come from a regex/grok/paint pattern's capture groups
  // instead of a delimiter. When set, the viewer segments lines by the pattern; `columns[].index`
  // = capture-group index. `delimiter` is unused/marker in this mode.
  pattern?: { regex: string; flags: string; fields: string[] };
}

// Tab State - stores per-file state for inactive tabs
interface TabState {
  id: string;
  filePath: string;
  // Optional human label shown in the tab bar instead of the basename (used by single
  // sessions, whose filePath is a synthetic composite:// id with no meaningful basename).
  displayName?: string;
  // For a single-session (composite) tab: the ordered member file paths it concatenates.
  // Lets us rebuild the composite in the main process when the user switches back to this
  // tab after opening one of the real member files (which tears the singleton composite down).
  compositeFiles?: string[];
  fileStats: FileStats | null;
  totalLines: number;
  scrollTop: number;
  scrollLeft: number;
  selectedLine: number | null;
  selectionStart: number | null;
  selectionEnd: number | null;
  searchResults: SearchResult[];
  currentSearchIndex: number;
  hiddenSearchMatches: HiddenMatch[];
  bookmarks: Bookmark[];
  highlights: HighlightConfig[];
  cachedLines: Map<number, LogLine>;
  splitFiles: string[];
  currentSplitIndex: number;
  // Loading state
  isLoading: boolean;
  loadingText: string;
  loadingPercent: number;
  // Minimap cache
  minimapData: Array<{ level: string | undefined }> | null;
  isLoaded: boolean; // true if file was fully loaded (skip re-indexing progress)
  // Column visibility
  columnConfig: ColumnConfig | null;
  // Analysis & filter state (preserved across tab switches)
  analysisResult: AnalysisResult | null;
  isFiltered: boolean;
  filteredLines: number | null;
  filteredLineNumbers: number[] | null;
  activeLevelFilter: string | null;
  appliedFilterSuggestion: { id: string; title: string } | null;
  // Filter suspension — config preserved, view temporarily shows all lines
  lastFilterConfig: FilterConfig | null;
  filterSuspended: 'auto' | 'manual' | null; // 'auto'=navigation triggered, 'manual'=user toggled
}

// Per-connection state for Live panel
interface LiveConnectionState {
  id: string;
  source: 'serial' | 'logcat' | 'ssh';
  displayName: string;
  detail: string;
  tempFilePath: string;
  tabId: string | null;
  linesReceived: number;
  connectedSince: number | null;
  connected: boolean;
  followMode: boolean;
  minimapLevels: Array<string | undefined>;
  lastLine: string;
  config: any;
}

// Application State - maintains current file state for backward compatibility
interface AppState {
  // Current file state (active tab)
  filePath: string | null;
  fileStats: FileStats | null;
  analysisResult: AnalysisResult | null;
  totalLines: number;
  filteredLines: number | null;
  filteredLineNumbers: number[] | null;
  isFiltered: boolean;
  activeLevelFilter: string | null;
  appliedFilterSuggestion: { id: string; title: string } | null;
  lastFilterConfig: FilterConfig | null;
  filterSuspended: 'auto' | 'manual' | null;
  searchResults: SearchResult[];
  currentSearchIndex: number;
  hiddenSearchMatches: HiddenMatch[];
  bookmarks: Bookmark[];
  highlights: HighlightConfig[];
  annotations: any[];
  annotationsByLine: Map<number, any[]>;
  showAnnotations: boolean;
  visibleStartLine: number;
  visibleEndLine: number;
  selectedLine: number | null;
  selectionStart: number | null;
  selectionEnd: number | null;
  activeScope: ScopeInfo | null;
  activeScopeDescriptor: ScopeDescriptor | null;
  savedRanges: Array<{ startLine: number; endLine: number }>;
  splitFiles: string[];
  currentSplitIndex: number;
  // Tab management
  tabs: TabState[];
  activeTabId: string | null;
  // Folder tree
  folders: FolderState[];
  // Column visibility
  columnConfig: ColumnConfig | null;
  // Notes file tracking
  currentNotesFile: string | null;
  // Folder search
  folderSearchResults: FolderSearchMatch[];
  isFolderSearching: boolean;
  // Terminal
  terminalVisible: boolean;
  terminalInitialized: boolean;
  activeTerminalTabId: string | null;
  // Bottom panel (tabbed)
  bottomPanelVisible: boolean;
  activeBottomTab: string | null;
  lastActiveBottomTab: string | null;
  // Search configs
  searchConfigs: SearchConfigDef[];
  searchConfigResults: Map<string, SearchResult[]>;
  // Video player
  videoSyncOffsetMs: number;
  videoFilePath: string | null;
  // Live panel (multi-connection)
  liveConnections: Map<string, LiveConnectionState>;
  activeConnectionId: string | null;
  liveSource: 'serial' | 'logcat' | 'ssh';
  sshProfiles: SshProfile[];
  // Baselines
  baselineList: BaselineRecord[];
  comparisonReport: ComparisonReport | null;
  // Context search
  contextDefinitions: ContextDefinitionDef[];
  contextResults: Map<string, ContextMatchGroupDef[]>;
  contextViewMode: 'tree' | 'lanes';
  contextGroupMode: 'separate' | 'combined';
  contextShowIncomplete: boolean;
  editingContextId: string | null;
  // Level visibility quick-toggle (persisted globally)
  hiddenLevels: Set<string>;
  levelBarFilterActive: boolean;
  // "Mute" patterns: rows whose text contains any of these are dimmed IN PLACE
  // (kept for context, not removed) via a render-time class. Persisted globally.
  mutePatterns: string[];
  mutedSize: 'normal' | 'small' | 'tiny'; // opt-in smaller font for muted lines (mute menu)
  // Traceback
  tracebackResult: any | null;
  tracebackSort: 'time' | 'score';
  tracebackFilterCat: string;
  // Time Align
  timeAlignOffsets: Map<string, number>;
  timeAlignTimestamps: Map<string, Array<{ lineNumber: number; epochMs: number }>>;
  timeAlignMinTime: number;
  timeAlignMaxTime: number;
  // Search Configs overview strip: align lanes by wall-clock time (shared axis) vs. by line position
  scOverviewAlignByTime: boolean;
  // Search Configs overview strip: collapse the per-pattern lanes into ONE lane
  // where every matched line is drawn once (a line matched by 2+ patterns is a
  // single grey mark) instead of repeating it across each pattern's lane.
  scOverviewCombine: boolean;
}

const state: AppState = {
  filePath: null,
  fileStats: null,
  analysisResult: null,
  totalLines: 0,
  filteredLines: null,
  filteredLineNumbers: null,
  isFiltered: false,
  activeLevelFilter: null,
  appliedFilterSuggestion: null,
  lastFilterConfig: null,
  filterSuspended: null,
  searchResults: [],
  currentSearchIndex: -1,
  hiddenSearchMatches: [],
  bookmarks: [],
  highlights: [],
  annotations: [],
  annotationsByLine: new Map(),
  showAnnotations: true,
  visibleStartLine: 0,
  visibleEndLine: 100,
  selectedLine: null,
  selectionStart: null,
  selectionEnd: null,
  activeScope: null,
  activeScopeDescriptor: null,
  savedRanges: [],
  splitFiles: [],
  currentSplitIndex: -1,
  tabs: [],
  activeTabId: null,
  folders: [],
  columnConfig: null,
  currentNotesFile: null,
  folderSearchResults: [],
  isFolderSearching: false,
  terminalVisible: false,
  terminalInitialized: false,
  activeTerminalTabId: null,
  bottomPanelVisible: false,
  activeBottomTab: null,
  lastActiveBottomTab: null,
  searchConfigs: [],
  searchConfigResults: new Map(),
  videoSyncOffsetMs: 0,
  videoFilePath: null,
  liveConnections: new Map<string, LiveConnectionState>(),
  activeConnectionId: null,
  liveSource: 'serial' as 'serial' | 'logcat' | 'ssh',
  sshProfiles: [],
  baselineList: [],
  comparisonReport: null,
  contextDefinitions: [],
  contextResults: new Map(),
  contextViewMode: 'tree' as 'tree' | 'lanes',
  contextGroupMode: 'separate' as 'separate' | 'combined',
  contextShowIncomplete: localStorage.getItem('logan-ctx-show-incomplete') !== 'false',
  editingContextId: null,
  hiddenLevels: new Set<string>(JSON.parse(localStorage.getItem('logan-hidden-levels') || '[]')),
  levelBarFilterActive: false,
  mutePatterns: JSON.parse(localStorage.getItem('logan-mute-patterns') || '[]'),
  mutedSize: (localStorage.getItem('logan-muted-size') as 'normal' | 'small' | 'tiny') || 'normal',
  tracebackResult: null,
  tracebackSort: 'time' as 'time' | 'score',
  tracebackFilterCat: 'all',
  timeAlignOffsets: new Map<string, number>(),
  timeAlignTimestamps: new Map<string, Array<{ lineNumber: number; epochMs: number }>>(),
  timeAlignMinTime: 0,
  timeAlignMaxTime: 0,
  scOverviewAlignByTime: localStorage.getItem('logan-sc-overview-time') === 'true',
  // Default ON: each matched line shows once (opt out to the per-pattern lanes).
  scOverviewCombine: localStorage.getItem('logan-sc-overview-combine') !== 'false',
};

// Constants
const BASE_LINE_HEIGHT = 20;
const BASE_FONT_SIZE = 13;
const BUFFER_LINES = 50;
const MAX_SCROLL_HEIGHT = 10000000; // 10 million pixels - safe for all browsers
// LRU cap on cached lines. At ~250 lines/viewport the old 5000 churned fully every
// ~0.4s during a fling, so nothing survived to the settle point or a direction reversal
// (=> re-fetch + white flash on every reversal). 60k lines is ~10-20MB (LogLine is a few
// hundred bytes) — cheap in Electron — and keeps tens of viewports resident so settle and
// short reversals are cache hits.
const CACHE_SIZE = 60000; // Max lines to keep in cache
const SCROLL_DEBOUNCE_MS = 16; // ~60fps
const PREFETCH_LINES = 100; // Lines to prefetch ahead of scroll direction

// Zoom settings
const ZOOM_MIN = 50;
const ZOOM_MAX = 200;
const ZOOM_STEP = 10;
let zoomLevel = 100; // Percentage (100 = default)

// Panel resize state
let isResizingSidebar = false;
let sidebarStartX = 0;
let sidebarStartWidth = 0;

// User settings (persisted to localStorage)
interface UserSettings {
  scrollSpeed: number;        // 10-100, percentage
  defaultFontSize: number;    // 10-20, pixels
  defaultGapThreshold: number; // 1-60, seconds
  autoAnalyze: boolean;
  minimapVisible: boolean;
  theme: 'dark' | 'paper';
  sidebarSections: Record<string, boolean>; // section-id → visible
}

const SIDEBAR_SECTIONS: { id: string; label: string; colorVar: string }[] = [
  { id: 'folders', label: 'Folders', colorVar: '--section-color-folders' },
  { id: 'bookmarks', label: 'Bookmarks', colorVar: '--section-color-bookmarks' },
  { id: 'highlights', label: 'Highlights', colorVar: '--section-color-highlights' },
];

const DEFAULT_SIDEBAR_SECTIONS: Record<string, boolean> = Object.fromEntries(
  SIDEBAR_SECTIONS.map(s => [s.id, true])
);

const DEFAULT_SETTINGS: UserSettings = {
  scrollSpeed: 30,
  defaultFontSize: 13,
  defaultGapThreshold: 5,
  autoAnalyze: false,
  minimapVisible: true,
  theme: 'dark',
  sidebarSections: { ...DEFAULT_SIDEBAR_SECTIONS },
};

let userSettings: UserSettings = { ...DEFAULT_SETTINGS };

function loadSettings(): void {
  try {
    const saved = localStorage.getItem('logan-settings');
    if (saved) {
      const parsed = JSON.parse(saved);
      userSettings = { ...DEFAULT_SETTINGS, ...parsed };
      // Deep-merge sidebarSections so new sections get defaults
      userSettings.sidebarSections = { ...DEFAULT_SIDEBAR_SECTIONS, ...(parsed.sidebarSections || {}) };
    }
  } catch (e) {
    console.warn('Failed to load settings from localStorage:', e);
    userSettings = { ...DEFAULT_SETTINGS };
  }
}

function saveSettings(): void {
  localStorage.setItem('logan-settings', JSON.stringify(userSettings));
}

function applySettings(): void {
  // Apply default font size to zoom level
  const fontSizeRatio = userSettings.defaultFontSize / BASE_FONT_SIZE;
  zoomLevel = Math.round(fontSizeRatio * 100);

  // Update gap threshold input if it exists
  const gapInput = document.getElementById('gap-threshold') as HTMLInputElement;
  if (gapInput) {
    gapInput.value = userSettings.defaultGapThreshold.toString();
  }

  // Apply theme
  applyTheme(userSettings.theme);

  // Apply sidebar section visibility
  applySidebarSectionVisibility();
}

function applySidebarSectionVisibility(): void {
  for (const section of SIDEBAR_SECTIONS) {
    // Hide/show activity bar buttons based on section visibility settings
    const btn = document.querySelector(`.activity-bar-btn[data-panel="${section.id}"]`) as HTMLElement;
    if (btn) {
      const visible = userSettings.sidebarSections[section.id] !== false;
      btn.style.display = visible ? '' : 'none';
    }
  }
}

function populateSidebarSectionToggles(): void {
  const container = document.getElementById('sidebar-section-toggles');
  if (!container) return;
  container.innerHTML = '';
  for (const section of SIDEBAR_SECTIONS) {
    const label = document.createElement('label');
    label.className = 'checkbox-label';

    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = userSettings.sidebarSections[section.id] !== false;
    checkbox.dataset.sectionId = section.id;

    const dot = document.createElement('span');
    dot.className = 'section-color-dot';
    const color = getComputedStyle(document.documentElement).getPropertyValue(section.colorVar).trim();
    dot.style.backgroundColor = color;

    const text = document.createTextNode(section.label);

    checkbox.addEventListener('change', () => {
      userSettings.sidebarSections[section.id] = checkbox.checked;
      saveSettings();
      applySidebarSectionVisibility();
    });

    label.appendChild(checkbox);
    label.appendChild(dot);
    label.appendChild(text);
    container.appendChild(label);
  }
}

function applyTheme(theme: string): void {
  document.documentElement.classList.remove('theme-paper');
  if (theme === 'paper') {
    document.documentElement.classList.add('theme-paper');
  }
}

// Word wrap setting
let wordWrapEnabled = false;

// Search direction and start line
let searchDirection: 'forward' | 'backward' = 'forward';

// Signature of the last completed Find search (file + pattern + options + filter
// generation). Lets a repeat search of the exact same thing reuse the cached
// results instead of re-scanning the whole file — pressing Enter again just
// advances to the next match. Reset when the file changes.
let lastFindSignature: string | null = null;
// Monotonic search generation. Each performSearch() bumps it; streamed events and the
// awaited result of any superseded search are dropped so overlapping searches can't
// stream matches into each other's results.
let searchGeneration = 0;

// O(1) line → matches lookup for highlight rendering. Rebuilt lazily whenever
// state.searchResults is REPLACED (detected by array-reference change), and appended
// to directly on the streaming path (same reference). Replaces a per-visible-line
// `state.searchResults.filter(...)` that was O(matches) × rows-per-frame — brutal
// while scrolling a 100k-match result set, especially mid-stream.
let searchLineIndex: Map<number, SearchResult[]> = new Map();
let searchLineIndexRef: SearchResult[] | null = null;

function rebuildSearchLineIndex(): void {
  const map = new Map<number, SearchResult[]>();
  for (const m of state.searchResults) {
    const arr = map.get(m.lineNumber);
    if (arr) arr.push(m); else map.set(m.lineNumber, [m]);
  }
  searchLineIndex = map;
  searchLineIndexRef = state.searchResults;
}

function addToSearchLineIndex(m: SearchResult): void {
  // If the array was replaced out from under us, rebuild once (it already includes m).
  if (searchLineIndexRef !== state.searchResults) { rebuildSearchLineIndex(); return; }
  const arr = searchLineIndex.get(m.lineNumber);
  if (arr) arr.push(m); else searchLineIndex.set(m.lineNumber, [m]);
}

function searchMatchesForLine(lineNumber: number): SearchResult[] | undefined {
  // Auto-rebuild if state.searchResults was replaced anywhere (file open, clear, tab
  // restore, final search result) — the reference check keeps us correct without
  // having to touch every assignment site.
  if (searchLineIndexRef !== state.searchResults) rebuildSearchLineIndex();
  return searchLineIndex.get(lineNumber);
}

// JSON formatting setting
let jsonFormattingEnabled = false;
let jsonOriginalFile: string | null = null; // Track original file when viewing formatted JSON
let esotraceDecodeEnabled = false;
let esotraceOriginalFile: string | null = null; // Track original file when viewing decoded esotrace

// Check if text contains JSON
function containsJson(text: string): boolean {
  // Quick check for JSON-like content
  const trimmed = text.trim();
  const firstChar = trimmed[0];
  return firstChar === '{' || firstChar === '[';
}

// Format JSON with syntax highlighting
// If skipSyntaxHighlight is true, just pretty-print without colors (for use with user highlights)
function formatJsonContent(text: string, skipSyntaxHighlight: boolean = false): string {
  // Simple approach: try to parse the entire line as JSON
  const trimmed = text.trim();

  try {
    const parsed = JSON.parse(trimmed);
    const prettyJson = JSON.stringify(parsed, null, 2);
    if (skipSyntaxHighlight) {
      // Return raw pretty-printed JSON - no escaping needed, will be escaped by caller
      return prettyJson;
    } else {
      // Apply syntax highlighting - this escapes HTML internally
      return syntaxHighlightJson(prettyJson);
    }
  } catch {
    // Not valid JSON, return escaped original
    if (skipSyntaxHighlight) {
      return text;
    } else {
      return escapeHtml(text);
    }
  }
}

// Escape HTML without sanitization (for pre-validated content like JSON)
function escapeHtmlSimple(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

// Simple JSON syntax highlighter using character scanning (no regex backtracking)
function syntaxHighlightJson(json: string): string {
  let result = '';
  let i = 0;

  while (i < json.length) {
    const char = json[i];

    // String (key or value)
    if (char === '"') {
      const start = i;
      i++; // skip opening quote
      while (i < json.length && json[i] !== '"') {
        if (json[i] === '\\' && i + 1 < json.length) {
          i += 2; // skip escaped char
        } else {
          i++;
        }
      }
      i++; // skip closing quote
      const str = json.slice(start, i);
      const escaped = str.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

      // Check if it's a key (followed by colon)
      let j = i;
      while (j < json.length && (json[j] === ' ' || json[j] === '\t')) j++;
      if (json[j] === ':') {
        result += `<span class="json-key">${escaped}</span>`;
      } else {
        result += `<span class="json-string">${escaped}</span>`;
      }
      continue;
    }

    // Number
    if (char === '-' || (char >= '0' && char <= '9')) {
      const start = i;
      if (char === '-') i++;
      while (i < json.length && json[i] >= '0' && json[i] <= '9') i++;
      if (i < json.length && json[i] === '.') {
        i++;
        while (i < json.length && json[i] >= '0' && json[i] <= '9') i++;
      }
      if (i < json.length && (json[i] === 'e' || json[i] === 'E')) {
        i++;
        if (i < json.length && (json[i] === '+' || json[i] === '-')) i++;
        while (i < json.length && json[i] >= '0' && json[i] <= '9') i++;
      }
      result += `<span class="json-number">${json.slice(start, i)}</span>`;
      continue;
    }

    // true/false/null keywords
    if (json.slice(i, i + 4) === 'true') {
      result += '<span class="json-boolean">true</span>';
      i += 4;
      continue;
    }
    if (json.slice(i, i + 5) === 'false') {
      result += '<span class="json-boolean">false</span>';
      i += 5;
      continue;
    }
    if (json.slice(i, i + 4) === 'null') {
      result += '<span class="json-null">null</span>';
      i += 4;
      continue;
    }

    // Structural characters and whitespace - escape and pass through
    const escaped = char === '<' ? '&lt;' : char === '>' ? '&gt;' : char === '&' ? '&amp;' : char;
    result += escaped;
    i++;
  }

  return result;
}

// Markdown preview
let isMarkdownFile = false;
let markdownPreviewMode = true; // Start in preview mode for md files
declare const marked: { parse: (text: string) => string };

// Get current line height based on zoom
function getLineHeight(): number {
  return Math.round(BASE_LINE_HEIGHT * (zoomLevel / 100));
}

// Get current font size based on zoom
function getFontSize(): number {
  return Math.round(BASE_FONT_SIZE * (zoomLevel / 100));
}

// Measure monospace character width at current zoom level
let _cachedCharWidth = 0;
let _charWidthZoom = 0;
function getCharWidth(): number {
  if (_charWidthZoom === zoomLevel && _cachedCharWidth > 0) return _cachedCharWidth;
  const span = document.createElement('span');
  span.style.cssText = `position:absolute;visibility:hidden;white-space:pre;font-family:var(--font-family);font-size:${getFontSize()}px;`;
  span.textContent = 'M';
  document.body.appendChild(span);
  _cachedCharWidth = span.getBoundingClientRect().width;
  document.body.removeChild(span);
  _charWidthZoom = zoomLevel;
  return _cachedCharWidth;
}

// Get line number gutter width (min-width 60px + padding-right 15px + margin-right 10px + border 1px)
const LINE_NUMBER_GUTTER_EXTRA = 86;

// Scroll state for optimizations
let lastScrollTop = 0;
let scrollDirection: 'up' | 'down' = 'down';
let scrollRAF: number | null = null;
let isScrolling = false;
let scrollEndTimer: ReturnType<typeof setTimeout> | null = null;
// In-flight getLines requests, keyed "<filterTag>:<start>-<end>". Lets overlapping
// loadVisibleLines() calls (per-frame load-RAF + the scroll-end safety net) SHARE one
// fetch for an identical range instead of each firing its own — so the settle fetch is
// never queued behind duplicate fling fetches, and stale frames don't pile on redundant
// IPC. Cleared in a finally when the request resolves.
const inFlightRanges = new Map<string, Promise<void>>();
