// === Highlight Groups ===

async function loadHighlightGroups(): Promise<void> {
  const result = await window.api.listHighlightGroups();
  if (result.success && result.groups) {
    highlightGroups = result.groups;
    updateHighlightGroupsUI();
  }
}

function updateHighlightGroupsUI(): void {
  const chipsContainer = elements.highlightGroupsChips;
  const deleteBtn = elements.btnDeleteHighlightGroup;

  if (highlightGroups.length === 0) {
    chipsContainer.innerHTML = '<span style="font-size:11px;color:var(--text-muted)">No saved groups</span>';
    deleteBtn.style.display = 'none';
    return;
  }

  chipsContainer.innerHTML = highlightGroups
    .map(g => `<span class="highlight-group-chip${g.id === activeHighlightGroupId ? ' active' : ''}" data-id="${g.id}" title="${escapeHtml(g.name)} (${g.highlights.length} rules)">${escapeHtml(g.name)}</span>`)
    .join('');

  // Show/hide delete button based on active group
  deleteBtn.style.display = activeHighlightGroupId ? '' : 'none';

  // Add click handlers to chips
  chipsContainer.querySelectorAll('.highlight-group-chip').forEach(chip => {
    chip.addEventListener('click', (e) => {
      const id = (e.target as HTMLElement).dataset.id!;
      applyHighlightGroup(id);
    });
  });
}

async function applyHighlightGroup(groupId: string, forceOn = false): Promise<void> {
  // Already active: the human ▶ toggles it OFF; an idempotent apply (forceOn — agent /
  // outfit) leaves it ON (a re-apply must never silently un-highlight).
  if (activeHighlightGroupId === groupId) {
    if (forceOn) return;
    await window.api.clearAllHighlights();
    state.highlights = [];
    activeHighlightGroupId = null;
    updateHighlightGroupsUI();
    updateHighlightsUI();
    renderVisibleLines();
    return;
  }

  const group = highlightGroups.find(g => g.id === groupId);
  if (!group) return;

  // Clear current highlights
  await window.api.clearAllHighlights();

  // Apply group's highlights
  for (const h of group.highlights) {
    await window.api.addHighlight(h);
  }

  // Reload highlights from backend
  const result = await window.api.listHighlights();
  if (result.success && result.highlights) {
    state.highlights = result.highlights;
  }

  activeHighlightGroupId = groupId;
  updateHighlightGroupsUI();
  updateHighlightsUI();
  renderVisibleLines();
}

// ── Uniform "description" editor for saveable entities ─────────────────────────
// Every saveable entity (tag/constant, search pattern, session, column layout,
// bookmark, highlight, trend property) carries an optional `description`. This modal
// PREFILLS the current text (unlike showTextInputModal's placeholder-only input) and
// lets you save an empty string to CLEAR it. Returns the new text, or null if cancelled.
function showDescriptionModal(current: string): Promise<string | null> {
  return new Promise((resolve) => {
    const overlay = document.createElement('div');
    overlay.className = 'modal';
    overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;';
    overlay.innerHTML = `
      <div class="modal-content" style="width:440px;">
        <div class="modal-header"><h3>Edit description</h3></div>
        <div class="modal-body">
          <div class="filter-group">
            <label>Purpose / why (optional — blank clears it). ⌘/Ctrl+Enter to save.</label>
            <textarea class="modal-input" rows="3" style="resize:vertical;width:100%;"></textarea>
          </div>
        </div>
        <div class="modal-footer">
          <button class="secondary-btn" data-action="cancel">Cancel</button>
          <button class="primary-btn" data-action="save">Save</button>
        </div>
      </div>`;
    const input = overlay.querySelector('textarea') as HTMLTextAreaElement;
    input.value = current;
    const close = (v: string | null) => { overlay.remove(); resolve(v); };
    (overlay.querySelector('[data-action="save"]') as HTMLButtonElement).addEventListener('click', () => close(input.value.trim()));
    (overlay.querySelector('[data-action="cancel"]') as HTMLButtonElement).addEventListener('click', () => close(null));
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) close(input.value.trim());
      else if (e.key === 'Escape') close(null);
    });
    overlay.addEventListener('click', (e) => { if (e.target === overlay) close(null); });
    document.body.appendChild(overlay);
    input.focus();
    input.select();
  });
}

// Prompt for a new description and persist via `save` (which receives '' to clear).
async function editEntityDescription(current: string | undefined, save: (desc: string) => void | Promise<void>): Promise<void> {
  const next = await showDescriptionModal(current || '');
  if (next === null) return; // cancelled
  await save(next);
  showToast(next ? 'Description saved' : 'Description cleared');
}

// Tooltip suffix: append an entity's description to a title string when present.
function descTitleSuffix(description?: string): string {
  return description ? `\n📝 ${description}` : '';
}

function showTextInputModal(title: string, label: string, placeholder: string): Promise<string | null> {
  return new Promise((resolve) => {
    const overlay = document.createElement('div');
    overlay.className = 'modal';
    overlay.style.cssText = 'display:flex;align-items:center;justify-content:center;';

    overlay.innerHTML = `
      <div class="modal-content" style="width:400px;">
        <div class="modal-header">
          <h3>${escapeHtml(title)}</h3>
        </div>
        <div class="modal-body">
          <div class="filter-group">
            <label>${escapeHtml(label)}</label>
            <input type="text" class="modal-input" placeholder="${escapeHtml(placeholder)}" autofocus>
          </div>
        </div>
        <div class="modal-footer">
          <button class="secondary-btn" data-action="cancel">Cancel</button>
          <button class="primary-btn" data-action="save">Save</button>
        </div>
      </div>
    `;

    const input = overlay.querySelector('input') as HTMLInputElement;
    const btnSave = overlay.querySelector('[data-action="save"]') as HTMLButtonElement;
    const btnCancel = overlay.querySelector('[data-action="cancel"]') as HTMLButtonElement;

    const close = (value: string | null) => {
      overlay.remove();
      resolve(value);
    };

    btnSave.addEventListener('click', () => {
      const val = input.value.trim();
      close(val || null);
    });
    btnCancel.addEventListener('click', () => close(null));
    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') {
        const val = input.value.trim();
        close(val || null);
      } else if (e.key === 'Escape') {
        close(null);
      }
    });
    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) close(null);
    });

    document.body.appendChild(overlay);
    input.focus();
  });
}

async function saveCurrentAsHighlightGroup(): Promise<void> {
  if (state.highlights.length === 0) {
    alert('No highlight rules to save. Add highlights first.');
    return;
  }

  const name = await showTextInputModal('Save Highlight Group', 'Group Name', 'e.g., Error patterns, Auth flow...');
  if (!name) return;

  const group: HighlightGroupData = {
    id: `hg-${Date.now()}`,
    name,
    highlights: state.highlights.map(h => ({ ...h })),
    createdAt: Date.now(),
  };

  const result = await window.api.saveHighlightGroup(group);
  if (result.success) {
    highlightGroups.push(group);
    activeHighlightGroupId = group.id;
    updateHighlightGroupsUI();
  }
}

async function deleteActiveHighlightGroup(): Promise<void> {
  if (!activeHighlightGroupId) return;

  const group = highlightGroups.find(g => g.id === activeHighlightGroupId);
  if (!group) return;

  if (!confirm(`Delete highlight group "${group.name}"?`)) return;

  const result = await window.api.deleteHighlightGroup(activeHighlightGroupId);
  if (result.success) {
    highlightGroups = highlightGroups.filter(g => g.id !== activeHighlightGroupId);
    activeHighlightGroupId = null;
    updateHighlightGroupsUI();
  }
}

// === Tab Management ===

function generateTabId(): string {
  return `tab-${Date.now()}-${Math.random().toString(36).substring(2, 11)}`;
}

function saveCurrentTabState(): void {
  if (!state.activeTabId) return;

  const tabIndex = state.tabs.findIndex(t => t.id === state.activeTabId);
  if (tabIndex === -1) return;

  // Save current state to the tab
  state.tabs[tabIndex] = {
    ...state.tabs[tabIndex],
    filePath: state.filePath || '',
    fileStats: state.fileStats,
    totalLines: state.totalLines,
    scrollTop: logViewerElement?.scrollTop || 0,
    scrollLeft: logViewerElement?.scrollLeft || 0,
    selectedLine: state.selectedLine,
    selectionStart: state.selectionStart,
    selectionEnd: state.selectionEnd,
    searchResults: state.searchResults,
    currentSearchIndex: state.currentSearchIndex,
    hiddenSearchMatches: state.hiddenSearchMatches,
    bookmarks: [...state.bookmarks],
    highlights: [...state.highlights],
    cachedLines: cachedLines.toMap(),
    splitFiles: state.splitFiles,
    currentSplitIndex: state.currentSplitIndex,
    minimapData: minimapData.length > 0 ? [...minimapData] : null,
    isLoaded: true,
    columnConfig: state.columnConfig,
    analysisResult: state.analysisResult,
    isFiltered: state.isFiltered,
    filteredLines: state.filteredLines,
    filteredLineNumbers: state.filteredLineNumbers,
    activeLevelFilter: state.activeLevelFilter,
    appliedFilterSuggestion: state.appliedFilterSuggestion,
    lastFilterConfig: state.lastFilterConfig,
    filterSuspended: state.filterSuspended,
  };
}

function restoreTabState(tab: TabState): void {
  // Fold state isn't persisted per-tab (v1) — drop it so a switched-in tab's
  // filter/scroll aren't shadowed by a stale fold view.
  resetFoldState();
  updateFoldButton();
  state.filePath = tab.filePath;
  state.fileStats = tab.fileStats;
  state.totalLines = tab.totalLines;
  state.selectedLine = tab.selectedLine;
  state.selectionStart = tab.selectionStart;
  state.selectionEnd = tab.selectionEnd;
  state.searchResults = tab.searchResults;
  state.currentSearchIndex = tab.currentSearchIndex;
  state.hiddenSearchMatches = tab.hiddenSearchMatches;
  state.bookmarks = [...tab.bookmarks];
  state.highlights = [...tab.highlights];
  state.splitFiles = tab.splitFiles;
  state.currentSplitIndex = tab.currentSplitIndex;
  state.columnConfig = tab.columnConfig;
  updateColumnHideStyle(); // apply this tab's column-hide rule (rows re-render on tab switch)

  // Restore analysis & filter state
  state.analysisResult = tab.analysisResult;
  state.isFiltered = tab.isFiltered;
  state.filteredLines = tab.filteredLines;
  state.filteredLineNumbers = tab.filteredLineNumbers;
  state.activeLevelFilter = tab.activeLevelFilter;
  state.appliedFilterSuggestion = tab.appliedFilterSuggestion;
  state.lastFilterConfig = tab.lastFilterConfig;
  state.filterSuspended = tab.filterSuspended;

  // Restore cached lines
  cachedLines.clear();
  tab.cachedLines.forEach((line, key) => cachedLines.set(key, line));

  // Update UI
  updateFileStatsUI();
  updateStatusBar();
  updateBookmarksUI();
  updateSearchUI();
  if (state.activeBottomTab === 'search-results') {
    renderSearchResultsList();
  }
}

function createTab(filePath: string): TabState {
  const tab: TabState = {
    id: generateTabId(),
    filePath,
    fileStats: null,
    totalLines: 0,
    scrollTop: 0,
    scrollLeft: 0,
    selectedLine: null,
    selectionStart: null,
    selectionEnd: null,
    searchResults: [],
    currentSearchIndex: -1,
    hiddenSearchMatches: [],
    bookmarks: [],
    highlights: [],
    cachedLines: new Map(),
    splitFiles: [],
    currentSplitIndex: -1,
    isLoading: false,
    loadingText: '',
    loadingPercent: 0,
    minimapData: null,
    isLoaded: false,
    columnConfig: null,
    analysisResult: null,
    isFiltered: false,
    filteredLines: null,
    filteredLineNumbers: null,
    activeLevelFilter: null,
    appliedFilterSuggestion: null,
    lastFilterConfig: null,
    filterSuspended: null,
  };
  return tab;
}

async function switchToTab(tabId: string): Promise<void> {
  if (tabId === state.activeTabId) return;

  const tab = state.tabs.find(t => t.id === tabId);
  if (!tab || !tab.filePath) return;

  // Deactivate split/diff when switching primary tab
  if (viewMode !== 'single') deactivateSplitView();

  // Save current tab state
  saveCurrentTabState();

  // Set new active tab
  state.activeTabId = tabId;

  // Sync loading overlay for new tab (may already be loading)
  syncLoadingOverlay();

  // Only show progress for files that haven't been loaded yet
  const isAlreadyLoaded = tab.isLoaded;
  if (!isAlreadyLoaded) {
    showProgress('Opening file...');
  }

  try {
    // Single-session tab: rebuild the composite in main before opening it. Opening any real
    // file (e.g. clicking one of the member tabs) sets activeComposite=null, so on the way
    // back we re-establish it from the stored member set; members reuse their cached handlers
    // so this is cheap. No-op'd naturally when the composite is still active (rebuild is idempotent).
    if (tab.compositeFiles && tab.compositeFiles.length >= 2) {
      await (window.api as any).createComposite(tab.compositeFiles, tab.displayName);
    }

    const result = await window.api.openFile(tab.filePath);

    if (result.success && result.info) {
      // Restore tab state
      restoreTabState(tab);

      // If tab had an active filter but filteredLineNumbers weren't saved, fetch them from backend
      if (state.isFiltered && !state.filteredLineNumbers) {
        state.filteredLineNumbers = await window.api.getFilteredLineNumbers() ?? null;
      }

      // Display mode manager handles mode transition for this tab
      await displayManager.switchTo(tab.filePath);

      // Update with fresh info from backend
      state.totalLines = result.info.totalLines;

      // Active scope is stored per-file in main — resync the breadcrumb for this tab
      void syncActiveScope();

      // Load bookmarks and highlights from backend (persisted per-file)
      if (result.bookmarks && Array.isArray(result.bookmarks)) {
        state.bookmarks = result.bookmarks;
        tab.bookmarks = result.bookmarks;
      }
      updateBookmarksUI();

      if (result.highlights && Array.isArray(result.highlights)) {
        state.highlights = result.highlights;
      }
      updateHighlightsUI();

      // Reload search configs, sessions, and context definitions for the new file
      loadSearchConfigs();
      loadSearchConfigSessions();
      loadContextDefinitions();

      // displayManager.switchTo() already called createLogViewer() via logViewerMode.activate()

      // Wait for DOM layout
      await new Promise(resolve => requestAnimationFrame(resolve));

      // Initialize visible range from saved scroll position
      if (logViewerElement) {
        const containerHeight = logViewerElement.clientHeight;
        const visibleLines = Math.ceil(containerHeight / getLineHeight());

        // Calculate visible range from saved scroll position
        const startLine = scrollTopToLine(tab.scrollTop);
        state.visibleStartLine = Math.max(0, startLine - BUFFER_LINES);
        state.visibleEndLine = Math.min(startLine + visibleLines + BUFFER_LINES, getTotalLines() - 1);
      }

      await loadVisibleLines();

      // Restore scroll position AFTER content is rendered
      await new Promise(resolve => requestAnimationFrame(resolve));
      if (logViewerElement) {
        logViewerElement.scrollTop = tab.scrollTop;
        logViewerElement.scrollLeft = tab.scrollLeft;
      }

      updateSplitNavigation();

      // Use cached minimap if available, otherwise rebuild
      if (tab.minimapData && tab.minimapData.length > 0) {
        minimapData = tab.minimapData;
        renderMinimap();
      } else if (!isAlreadyLoaded) {
        await buildMinimap();
      }

      // Restore analysis & filter UI
      updateAnalysisUI();
      updateLevelBadgeStyles();

      // Re-render annotations now that the viewer is laid out — the main process
      // pushed this file's annotations via 'annotations-changed' during openFile,
      // but the bar was rebuilt empty by createLogViewer afterwards.
      renderAnnotationBar();
      renderAnnotationsPanel();
      renderMinimapMarkers();

      // Mark as loaded
      tab.isLoaded = true;

      // Change terminal directory to new file's folder
      terminalCdToFile(tab.filePath);
    }
  } finally {
    hideProgress();
  }

  renderTabBar();
  // Reveal the newly-active file in the folder tree (auto: quiet, panel-aware).
  void revealActiveFileInTree({ auto: true });
}

function closeTab(tabId: string): void {
  const tabIndex = state.tabs.findIndex(t => t.id === tabId);
  if (tabIndex === -1) return;

  // If closing the secondary tab in split/diff mode, deactivate
  if (viewMode !== 'single' && tabId === splitDiffState.secondaryTabId) {
    deactivateSplitView();
  }

  // Remove the tab
  state.tabs.splice(tabIndex, 1);

  // If closing the active tab, switch to another
  if (tabId === state.activeTabId) {
    if (state.tabs.length > 0) {
      // Switch to the previous tab, or the first one
      const newIndex = Math.min(tabIndex, state.tabs.length - 1);
      switchToTab(state.tabs[newIndex].id);
    } else {
      // No more tabs - reset to welcome state
      resetToWelcomeState();
    }
  }

  renderTabBar();
  // setupHelpTooltips moved outside init
}

// Reset the viewer back to the empty welcome state (no tabs open).
function resetToWelcomeState(): void {
  state.activeTabId = null;
  state.filePath = null;
  state.fileStats = null;
  state.totalLines = 0;
  state.searchResults = [];
  state.currentSearchIndex = -1;
  state.hiddenSearchMatches = [];
  state.bookmarks = [];
  state.highlights = [];
  cachedLines.clear();
  state.splitFiles = [];
  state.currentSplitIndex = -1;

  // Show welcome message
  if (logViewerWrapper) {
    logViewerWrapper.remove();
    logViewerWrapper = null;
    logViewerElement = null;
    logContentElement = null;
  }
  elements.welcomeMessage.classList.remove('hidden');
  closeBottomPanel();
  updateStatusBar();
  updateFileStatsUI();
  updateBookmarksUI();
  updateHighlightsUI();
}

// Close every open tab and return to the welcome state.
function closeAllTabs(): void {
  if (state.tabs.length === 0) return;
  if (viewMode !== 'single') deactivateSplitView();
  state.tabs = [];
  resetToWelcomeState();
  renderTabBar();
}

// Close every tab except the given one, keeping it active.
function closeOtherTabs(keepTabId: string): void {
  const others = state.tabs.filter((t) => t.id !== keepTabId).map((t) => t.id);
  if (others.length === 0) return;
  // Drop split/diff if the secondary pane is one of the tabs being closed.
  if (viewMode !== 'single' && splitDiffState.secondaryTabId && others.includes(splitDiffState.secondaryTabId)) {
    deactivateSplitView();
  }
  state.tabs = state.tabs.filter((t) => t.id === keepTabId);
  if (state.activeTabId !== keepTabId) switchToTab(keepTabId);
  renderTabBar();
}

function renderTabBar(): void {
  elements.tabsContainer.innerHTML = '';
  if (state.tabs.length === 0) {
    return;
  }

  for (const tab of state.tabs) {
    const tabElement = document.createElement('div');
    tabElement.className = `tab${tab.id === state.activeTabId ? ' active' : ''}`;
    tabElement.dataset.tabId = tab.id;

    const fileName = getFileName(tab.filePath);
    // Single sessions carry an explanatory label (built from their member basenames); real
    // files fall back to the basename. The tooltip lists the member files for a session.
    let displayName = tab.displayName || fileName;
    const tabTooltip = tab.compositeFiles && tab.compositeFiles.length
      ? `Single session:\n${tab.compositeFiles.map((f) => getFileName(f)).join('\n')}`
      : tab.filePath;

    // Add split indicator if part of a split set
    if (tab.splitFiles.length > 0 && tab.currentSplitIndex >= 0) {
      displayName += ` [${tab.currentSplitIndex + 1}/${tab.splitFiles.length}]`;
    }

    tabElement.innerHTML = `
      <span class="tab-title" title="${escapeHtml(tabTooltip)}">${escapeHtml(displayName)}</span>
      <button class="tab-close" data-tab-id="${tab.id}" title="Close">&times;</button>
    `;

    // Tab click - switch to tab
    tabElement.addEventListener('click', (e) => {
      const target = e.target as HTMLElement;
      if (!target.classList.contains('tab-close')) {
        switchToTab(tab.id);
      }
    });

    // Close button click
    const closeBtn = tabElement.querySelector('.tab-close') as HTMLButtonElement;
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      closeTab(tab.id);
    });

    // Context menu for tabs
    tabElement.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      showFileContextMenu(e as MouseEvent, tab.filePath, tab.id);
    });

    elements.tabsContainer.appendChild(tabElement);
  }
}

function showFolderContextMenu(e: MouseEvent, folderPath: string): void {
  document.querySelector('.tab-context-menu')?.remove();
  const menu = document.createElement('div');
  menu.className = 'tab-context-menu';
  menu.innerHTML = `<div class="tab-context-item" data-action="search-folder">Search in this folder…</div>`
    + `<div class="tab-context-separator"></div>`
    + `<div class="tab-context-item" data-action="open-terminal">Open Terminal Here</div>`
    + `<div class="tab-context-item" data-action="decode-esotrace-folder">Decode esotrace files here</div>`
    + `<div class="tab-context-separator"></div>`
    + `<div class="tab-context-item" data-action="copy-path">Copy Path</div>`;
  menu.style.cssText = `position:fixed;left:${e.clientX}px;top:${e.clientY}px;`;
  document.body.appendChild(menu);
  menu.querySelector('[data-action="search-folder"]')?.addEventListener('click', () => {
    menu.remove();
    void searchInFolder(folderPath);
  });
  menu.querySelector('[data-action="open-terminal"]')?.addEventListener('click', () => {
    menu.remove();
    void openTerminalAtFolder(folderPath);
  });
  menu.querySelector('[data-action="decode-esotrace-folder"]')?.addEventListener('click', () => {
    menu.remove();
    void decodeEsotraceFilesInFolder(folderPath);
  });
  menu.querySelector('[data-action="copy-path"]')?.addEventListener('click', () => {
    navigator.clipboard.writeText(folderPath);
    menu.remove();
  });
  // Close on click outside — must NOT fire on the menu itself, otherwise the
  // mousedown would tear the menu down before its item click handler runs.
  const close = (ev: MouseEvent) => {
    if (menu.contains(ev.target as Node)) return;
    menu.remove();
    document.removeEventListener('mousedown', close);
  };
  setTimeout(() => document.addEventListener('mousedown', close), 0);
}

// Act on the descriptor returned by a file-handler run (src/main/fileHandlers.ts).
// Viewer/open actions run here in the renderer; transform/folder handlers (Phase 2)
// do their work in main and return one of these descriptors.
async function dispatchFileHandlerResult(res: FileHandlerResult): Promise<void> {
  switch (res.action) {
    case 'open-log':
      if (res.path) await loadFile(res.path);
      break;
    case 'open-panel':
      if (res.panel === 'video' && res.path) { loadVideoFromPath(res.path); openBottomTab('video'); }
      else if (res.panel === 'image' && res.path) { openImageInPanel(res.path); }
      else showToast(`No viewer available for ${res.panel || 'this file'}`);
      break;
    case 'open-folder':
      showToast('Folder handlers are coming soon');
      break;
    case 'toast':
      showToast(res.message || '');
      break;
  }
}

function showFileContextMenu(e: MouseEvent, filePath: string, tabId?: string, fileHandlers?: FileHandlerInfo[]): void {
  // Remove existing context menu
  const existing = document.querySelector('.tab-context-menu');
  if (existing) existing.remove();

  const menu = document.createElement('div');
  menu.className = 'tab-context-menu';

  const fileName = getFileName(filePath);
  const items: string[] = [];

  // "Open with…" — the file-handler registry's actions for this entry, default first.
  if (fileHandlers && fileHandlers.length > 0) {
    for (const h of fileHandlers) {
      const label = `${h.icon ? h.icon + ' ' : ''}${escapeHtml(h.label)}${h.isDefault ? ' <span class="tab-context-hint">default</span>' : ''}`;
      items.push(`<div class="tab-context-item" data-action="fh:${escapeHtml(h.id)}">${label}</div>`);
    }
    items.push(`<div class="tab-context-separator"></div>`);
  }

  items.push(`<div class="tab-context-item" data-action="copy-name">Copy Name</div>`);
  items.push(`<div class="tab-context-item" data-action="copy-path">Copy Path</div>`);
  items.push(`<div class="tab-context-item" data-action="copy-all">Copy All Content</div>`);
  items.push(`<div class="tab-context-item" data-action="show-in-folder">Show in Folder</div>`);

  // Split/Diff only for non-active tabs when there are 2+ tabs
  if (tabId && tabId !== state.activeTabId && state.tabs.length >= 2) {
    items.push(`<div class="tab-context-separator"></div>`);
    items.push(`<div class="tab-context-item" data-action="split">Open in Split View</div>`);
    items.push(`<div class="tab-context-item" data-action="diff">Compare with Current Tab</div>`);
  }

  // Close tab
  if (tabId) {
    items.push(`<div class="tab-context-separator"></div>`);
    items.push(`<div class="tab-context-item" data-action="close">Close Tab</div>`);
    if (state.tabs.length >= 2) {
      items.push(`<div class="tab-context-item" data-action="close-others">Close Other Tabs</div>`);
    }
  }
  if (tabId && state.tabs.length >= 1) {
    items.push(`<div class="tab-context-item" data-action="close-all">Close All Tabs</div>`);
  }

  menu.innerHTML = items.join('');

  menu.style.left = `${e.clientX}px`;
  menu.style.top = `${e.clientY}px`;
  document.body.appendChild(menu);

  // Handle clicks
  menu.addEventListener('click', async (ev) => {
    const target = (ev.target as HTMLElement).closest('.tab-context-item') as HTMLElement;
    if (!target) return;
    const action = target.dataset.action;
    menu.remove();
    if (action && action.startsWith('fh:')) {
      const id = action.slice(3);
      await dispatchFileHandlerResult(await window.api.runFileHandler(id, { path: filePath }));
      return;
    }
    switch (action) {
      case 'copy-name':
        navigator.clipboard.writeText(fileName);
        break;
      case 'copy-path':
        navigator.clipboard.writeText(filePath);
        break;
      case 'copy-all':
        await copyAllFileContent(filePath);
        break;
      case 'show-in-folder':
        window.api.showItemInFolder(filePath);
        break;
      case 'split':
        if (tabId) activateSplitView(tabId);
        break;
      case 'diff':
        if (tabId) activateDiffView(tabId);
        break;
      case 'close':
        if (tabId) closeTab(tabId);
        break;
      case 'close-others':
        if (tabId) closeOtherTabs(tabId);
        break;
      case 'close-all':
        closeAllTabs();
        break;
    }
  });

  // Close on click outside
  const closeMenu = (ev: MouseEvent) => {
    if (!menu.contains(ev.target as Node)) {
      menu.remove();
      document.removeEventListener('click', closeMenu);
    }
  };
  setTimeout(() => document.addEventListener('click', closeMenu), 0);
}

async function copyAllFileContent(filePath: string): Promise<void> {
  const result = await window.api.readFileContent(filePath);
  if (!result.success) {
    alert(result.error || 'Failed to read file');
    return;
  }
  if (result.sizeMB && result.sizeMB > 10) {
    const proceed = confirm(`This file is ${result.sizeMB.toFixed(1)}MB. Copying to clipboard may be slow. Continue?`);
    if (!proceed) return;
  }
  if (result.content !== undefined) {
    await navigator.clipboard.writeText(result.content);
  }
}

function findTabByFilePath(filePath: string): TabState | undefined {
  return state.tabs.find(t => t.filePath === filePath);
}

// Start the app
init();

// Setup help tooltips after init
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', () => setupHelpTooltips());
} else {
  setupHelpTooltips();
}
